const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');let motion=!reduced.matches;const motionButton=document.querySelector('.motion-control');const fold=document.querySelector('.fold-object');let pointerX=0,pointerY=0,framePending=false;
function setMotion(value){motion=value;document.body.classList.toggle('motion-off',!motion);document.documentElement.style.scrollBehavior=motion?'smooth':'auto';motionButton.innerHTML=motion?'MOTION ON <span>Ⅱ</span>':'MOTION OFF <span>▶</span>';motionButton.setAttribute('aria-pressed',String(!motion));if(!motion)fold.style.transform='rotateX(24deg) rotateZ(-12deg)';else update();}
if(motion)document.body.classList.add('js-motion');setMotion(motion);motionButton.addEventListener('click',()=>setMotion(!motion));reduced.addEventListener('change',event=>setMotion(!event.matches));
const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}})},{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
function update(){const total=document.documentElement.scrollHeight-innerHeight;document.querySelector('.progress').style.width=`${total>0?scrollY/total*100:0}%`;if(motion&&scrollY<1100){const amount=Math.min(scrollY/900,1);fold.style.transform=`translateY(${amount*-30}px) rotateX(${24+pointerY*5-amount*16}deg) rotateY(${pointerX*6}deg) rotateZ(${-12+amount*14}deg)`;document.querySelector('.p1').style.transform=`rotateY(${-26+amount*23}deg)`;document.querySelector('.p3').style.transform=`rotateY(${26-amount*23}deg)`;}framePending=false;}
function schedule(){if(!framePending){framePending=true;requestAnimationFrame(update)}}addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule);document.querySelector('.fold-scene').addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;const r=e.currentTarget.getBoundingClientRect();pointerX=(e.clientX-r.left)/r.width-.5;pointerY=(e.clientY-r.top)/r.height-.5;schedule()});document.querySelector('.fold-scene').addEventListener('pointerleave',()=>{pointerX=pointerY=0;schedule()});
function clock(){document.querySelector('#clock').textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())+' IST'}clock();setInterval(clock,60000);document.querySelector('#year').textContent=new Date().getFullYear();
document.querySelector('#copy-email').addEventListener('click',async()=>{const status=document.querySelector('#copy-status');try{await navigator.clipboard.writeText('jayamsrivastava99@gmail.com');status.textContent='Email copied.'}catch{status.textContent='Select the email address to copy it.'}setTimeout(()=>status.textContent='',3500)});schedule();

fold.addEventListener('animationend',()=>{fold.style.animation='none';schedule()});
